/// Renders an on-brand milestone icon by its symbol NAME (stroked, tinted), sized
/// to `side`. Falls back to nil if the name isn't in the set (caller uses the SF
/// Symbol then).
struct MilestoneIconArtView: View {
    let name: String
    let color: Color
    var body: some View {
        if let art = MilestoneIconArt.byName[name] {
            Canvas { ctx, size in
                let scale = size.width / art.viewBox
                let t = CGAffineTransform(scaleX: scale, y: scale)
                for d in art.paths {
                    let p = SVGPath.parse(d).applying(t)
                    ctx.stroke(p, with: .color(color),
                               style: StrokeStyle(lineWidth: 1.25 * scale, lineCap: .round, lineJoin: .round))
                }
            }
        }
    }
}
